import React, { useState, useEffect } from 'react';

function AdminLoginModal({ adminToken, setAdminToken, adminInfo, setAdminInfo }) {
  const [tokenInput, setTokenInput] = useState('');
  const [nameInput, setNameInput] = useState('');
  const [passwordInput, setPasswordInput] = useState('');

  useEffect(() => {
    // Verify token on mount if present
    if (adminToken && !adminInfo) {
      fetch(`/api/admins?token=${encodeURIComponent(adminToken)}`)
        .then(r => r.json())
        .then(list => {
          if (list && list.length) setAdminInfo(list[0]);
        })
        .catch(() => {});
    }
  }, [adminToken, adminInfo, setAdminInfo]);

  const login = () => {
    const t = tokenInput.trim();
    if (!t) return alert('أدخل رمز الأدمن');
    fetch(`/api/admins?token=${encodeURIComponent(t)}`)
      .then(r => r.json())
      .then(list => {
        if (list && list.length) {
          setAdminToken(t);
          setAdminInfo(list[0]);
          localStorage.setItem('adminToken', t);
          setTokenInput('');
          // close modal
          document.querySelectorAll('[data-bs-dismiss="modal"]').forEach(b => b.click());
        } else {
          alert('رمز الأدمن غير صحيح');
        }
      })
      .catch(() => alert('خطأ في التحقق من الرمز'));
  };

  const loginWithPassword = () => {
    const name = nameInput.trim();
    const pw = passwordInput;
    if (!name || !pw) return alert('الرجاء إدخال الاسم و كلمة المرور');
    fetch('/api/admins/login', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name, password: pw }) })
      .then(r => r.json())
      .then(data => {
        if (data && data.token && data.admin) {
          setAdminToken(data.token);
          setAdminInfo(data.admin);
          localStorage.setItem('adminToken', data.token);
          setNameInput(''); setPasswordInput('');
          document.querySelectorAll('[data-bs-dismiss="modal"]').forEach(b => b.click());
        } else {
          alert('فشل تسجيل الدخول');
        }
      })
      .catch(() => alert('خطأ أثناء تسجيل الدخول'));
  };

  const logout = () => {
    setAdminToken('');
    setAdminInfo(null);
    localStorage.removeItem('adminToken');
  };

  return (
    <div className="modal fade" id="adminLoginModal" tabIndex="-1" aria-hidden="true">
      <div className="modal-dialog">
        <div className="modal-content">
          <div className="modal-header">
            <h5 className="modal-title">تسجيل دخول الأدمن</h5>
            <button type="button" className="btn-close" data-bs-dismiss="modal" aria-label="Close"></button>
          </div>
          <div className="modal-body">
            {adminInfo ? (
              <div className="d-flex align-items-center">
                <img src={adminInfo.photo || 'https://via.placeholder.com/64'} alt={adminInfo.name} className="rounded-circle me-3" style={{width:64,height:64,objectFit:'cover'}} />
                <div>
                  <p>مرحبًا، أنت متصل كأدمن: <strong>{adminInfo.name}</strong> {adminInfo.isOwner ? '(مالك)' : ''}</p>
                  <button className="btn btn-danger" onClick={logout} data-bs-dismiss="modal">تسجيل الخروج</button>
                </div>
              </div>
            ) : (
              <div>
                <label className="form-label">أدخل رمز الأدمن</label>
                <input className="form-control" type="password" value={tokenInput} onChange={e => setTokenInput(e.target.value)} onKeyDown={e => e.key === 'Enter' && login()} />
                <div className="mt-3 d-flex justify-content-end">
                  <button className="btn btn-secondary me-2" data-bs-dismiss="modal">إغلاق</button>
                  <button className="btn btn-primary" onClick={login}>دخول</button>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

export default AdminLoginModal;
